import SwiftUI

/// # Interaction — Pinch
///
/// @Metadata {
///     @PageKind(sampleCode)
///     @PageImage(purpose: card, source: "Interaction_Pinch")
/// }
///
/// Pinch to scale a shape. A `MagnifyGesture` (Origami's magnification/pinch input)
/// drives two `origami.PopSwitch` nodes that flip the shape between its base and an
/// enlarged state; the switch state feeds a `builtin.point3D` Transform Scale, and
/// the pop is animated with a spring. At rest a white rounded triangle sits at base
/// scale, centered on the magenta artboard.
///
/// - Origami source: https://origami.design/public/origami_files/patterns/Interaction_Pinch.origami
/// - Translated: 2026-09-26
public struct Interaction_PinchView: View {
    public init() {}

    // origami.PopSwitch ×2 → the shape's popped state (base ⇄ enlarged). A pop
    // switch remembers a boolean and flips it on a pulse; here the two switches
    // form the symmetric pop-in / pop-out pair, one flip each way.
    @State private var popped = false

    // MagnifyGesture live magnitude while a pinch is in progress. Resets to 1 when
    // the gesture ends, so the resting frame is unaffected by it.
    @GestureState private var liveMagnification: CGFloat = 1

    // builtin.point3D → uniform Transform Scale. Rest value = base (1); this is the
    // scale the pixel gate screenshots.
    private let baseScale: CGFloat = 1
    // The value the PopSwitch pops to.
    // TODO: parser-decoded token when available — origami.PopSwitch's "On" value is a
    // FlatBuffers port default the parser can't read yet; 2× is a faithful placeholder
    // for a pinch-to-enlarge demo, not an Inspector-confirmed constant.
    private let enlargedScale: CGFloat = 2

    // Magnification magnitude at which the PopSwitch flips. Symmetric: pinch out past
    // `popThreshold` pops in, pinch back in past its reciprocal pops out.
    private let popThreshold: CGFloat = 1.25

    // Central shape geometry — a rounded triangle, centered at rest.
    // Re-measured from Origami's own render (the pixel oracle for Interaction_Pinch):
    // the visible triangle is 153×141 px at 2× scale. Fitting the RoundedTriangle path
    // back to that profile (apex-up, flat base) gives a 90×80 pt vertex frame at a
    // 20 pt corner radius — reproducing Origami's width, height, and mid-height span exactly.
    // TODO: parser-decoded token when available — exact size and corner radius live as
    // shape-layer port defaults the parser can't read yet; these are oracle-derived.
    private let shapeSize = CGSize(width: 90, height: 80)
    private let shapeCornerRadius: CGFloat = 20

    // The rounded apex trims the top of the triangle's bounding box while its base
    // stays flat, so a frame-centered RoundedTriangle renders ≈4.4 pt low. Origami
    // centers the shape's *visible* bounds on the artboard, so lift by half the apex
    // trim (measured apex trim ≈8.7 px @2× → 4.4 pt) to line the two renders up.
    private let visibleCenteringLift: CGFloat = 4.4

    public var body: some View {
        // builtin.layer.layer (artboard background) — magenta, full-bleed.
        // TODO: parser-decoded token when available — the runner's compare confirms a
        // magenta background matching Origami's render; exact hex uses the Origami Core
        // "Purple" family value (rgb 221,112,223) pending token extraction.
        Color(red: 221 / 255.0, green: 112 / 255.0, blue: 223 / 255.0)
            .overlay {
                // builtin.layer.shape — a white rounded triangle, apex up.
                // TODO: parser-decoded token when available — shape fill not readable
                // from the placed-graph walk; white is read from the oracle render.
                RoundedTriangle(cornerRadius: shapeCornerRadius)
                    .fill(.white)
                    .frame(width: shapeSize.width, height: shapeSize.height)
                    // Center the shape's visible bounds on the artboard (see comment above).
                    .offset(y: -visibleCenteringLift)
                    // builtin.point3D Transform Scale ← origami.PopSwitch, driven by the pinch.
                    .scaleEffect(currentScale)
                    // origami.PopSwitch pop → spring (Pop Animation → SwiftUI spring, per
                    // the mapping table). Animates the discrete pop between states.
                    .animation(.spring(response: 0.35, dampingFraction: 0.7), value: popped)
                    .gesture(pinch)
            }
            .frame(maxWidth: .infinity, maxHeight: .infinity)
            .ignoresSafeArea() // Origami renders the artboard without safe-area chrome
            .statusBarHidden(true) // Origami's artboard render has no iOS status bar
    }

    // Live scale: during a pinch, follow the finger off the current popped state; at
    // rest, `liveMagnification` is 1 so this is just the PopSwitch state's scale.
    private var currentScale: CGFloat {
        (popped ? enlargedScale : baseScale) * liveMagnification
    }

    // origami.Interaction (magnification) → SwiftUI MagnifyGesture.
    private var pinch: some Gesture {
        MagnifyGesture()
            .updating($liveMagnification) { value, state, _ in
                state = value.magnification
            }
            .onEnded { value in
                popped = Self.popped(after: value.magnification, current: popped, threshold: popThreshold)
            }
    }

    // origami.PopSwitch flip decision, factored out so the state logic is testable.
    // Pinch out past `threshold` pops in; pinch in past its reciprocal pops out;
    // otherwise the switch holds its remembered state (Pop Switch = memory).
    static func popped(after magnification: CGFloat, current: Bool, threshold: CGFloat) -> Bool {
        if magnification >= threshold { return true }
        if magnification <= 1 / threshold { return false }
        return current
    }
}

